import requests, numpy as np, pandas as pd, matplotlib.pyplot as plt
pd.set_option('display.width',250); pd.set_option('display.max_rows',200)
AA3={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I',
 'LEU':'L','LYS':'K','MET':'M','MSE':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'}
def fetch_raw(pid):
    r=requests.get(f"https://files.rcsb.org/download/{pid}.pdb",timeout=60)
    if r.status_code==200 and not r.text.lstrip().startswith('<'): return 'pdb',r.text
    return 'cif',requests.get(f"https://files.rcsb.org/download/{pid}.cif",timeout=60).text
def finalize(ch):
    return {c:[{'resi':int(k[0]),'icode':k[1],'resn':v['resn'],'aa':AA3.get(v['resn'],'X'),'atoms':v['atoms']}
               for k,v in sorted(d.items(),key=lambda x:(int(x[0][0]),x[0][1]))] for c,d in ch.items()}
def parse_pdb_text(txt):
    ch={}; het=[]
    for ln in txt.splitlines():
        if ln.startswith('ENDMDL'): break
        if not ln.startswith(('ATOM','HETATM')) or ln[16] not in (' ','A'): continue
        resn=ln[17:20].strip(); c=ln[21]; resi=ln[22:26].strip(); ic=ln[26]; name=ln[12:16].strip()
        xyz=np.array([float(ln[30:38]),float(ln[38:46]),float(ln[46:54])])
        if resn in AA3:
            d=ch.setdefault(c,{}).setdefault((resi,ic),{'resn':resn,'atoms':{}}); d['atoms'][name]=xyz
        elif resn not in ('HOH','DOD'): het.append((c,resn,resi,name,xyz))
    return finalize(ch),het
def parse_cif_text(txt):
    lines=txt.splitlines(); i=0
    while i<len(lines):
        if lines[i].strip()=='loop_' and lines[i+1].strip().startswith('_atom_site.'):
            cols=[]; j=i+1
            while lines[j].strip().startswith('_atom_site.'): cols.append(lines[j].strip().split('.')[1]); j+=1
            idx={c:k for k,c in enumerate(cols)}; ch={}; het=[]
            while j<len(lines) and not lines[j].strip().startswith(('loop_','#','_')):
                f=lines[j].split()
                if len(f)>=len(cols) and f[idx['pdbx_PDB_model_num']]=='1' and f[idx['label_alt_id']] in ('.','A'):
                    resn=f[idx['label_comp_id']]; c=f[idx['auth_asym_id']]; resi=f[idx['auth_seq_id']]
                    name=(f[idx['auth_atom_id']] if 'auth_atom_id' in idx else f[idx['label_atom_id']]).strip('"')
                    xyz=np.array([float(f[idx['Cartn_x']]),float(f[idx['Cartn_y']]),float(f[idx['Cartn_z']])])
                    if resn in AA3:
                        d=ch.setdefault(c,{}).setdefault((resi,' '),{'resn':resn,'atoms':{}}); d['atoms'][name]=xyz
                    elif resn not in ('HOH','DOD'): het.append((c,resn,resi,name,xyz))
                j+=1
            return finalize(ch),het
        i+=1
def get(pid):
    k,t=fetch_raw(pid); return parse_pdb_text(t) if k=='pdb' else parse_cif_text(t)
def kabsch(P,Q):
    pc=P.mean(0); qc=Q.mean(0); U,S,Vt=np.linalg.svd((P-pc).T@(Q-qc))
    R=Vt.T@np.diag([1,1,np.sign(np.linalg.det(Vt.T@U.T))])@U.T; return R,qc-R@pc
def nw_fast(S,g=-0.6):
    n,m=S.shape; F=np.zeros((n+1,m+1)); F[0,1:]=g*np.arange(1,m+1); F[1:,0]=g*np.arange(1,n+1); jj=np.arange(m+1)
    for i in range(1,n+1):
        G=np.empty(m+1); G[0]=-1e9; G[1:]=np.maximum(F[i-1,:-1]+S[i-1],F[i-1,1:]+g)
        b=np.empty(m+1); b[0]=F[i,0]; b[1:]=G[1:]-g*jj[1:]
        F[i]=np.maximum.accumulate(b)+g*jj
    i,j=n,m; pairs=[]
    while i>0 and j>0:
        if abs(F[i,j]-(F[i,j-1]+g))<1e-9: j-=1
        elif abs(F[i,j]-(F[i-1,j-1]+S[i-1,j-1]))<1e-9: pairs.append((i-1,j-1)); i-=1; j-=1
        else: i-=1
    return pairs[::-1]
def tmalign(Xq,Xt):
    n,m=len(Xq),len(Xt); L=min(n,m); d0=max(1.24*(L-15)**(1/3)-1.8,0.5)
    seeds=[(i,j,Ls) for Ls in [L,L//2,L//4] if Ls>=12
           for i in range(0,n-Ls+1,max(1,Ls//2)) for j in range(0,m-Ls+1,max(1,Ls//2))]
    best=(0,None,None,None)
    for si,sj,Ls in seeds:
        R,t=kabsch(Xq[si:si+Ls],Xt[sj:sj+Ls]); pairs=None
        for it in range(8):
            Xm=Xq@R.T+t; D=np.linalg.norm(Xm[:,None,:]-Xt[None,:,:],axis=2); newp=nw_fast(1/(1+(D/d0)**2))
            if pairs==newp: break
            pairs=newp; cur=np.array(pairs)
            for cut in (d0+4,d0+2,d0):
                Xm=Xq@R.T+t; dd=np.linalg.norm(Xm[cur[:,0]]-Xt[cur[:,1]],axis=1); sel=cur[dd<cut]
                if len(sel)<10: break
                R,t=kabsch(Xq[sel[:,0]],Xt[sel[:,1]])
        if not pairs: continue
        Xm=Xq@R.T+t; ix=np.array(pairs); d=np.linalg.norm(Xm[ix[:,0]]-Xt[ix[:,1]],axis=1)
        tm=float(np.sum(1/(1+(d/d0)**2))/L)
        if tm>best[0]: best=(tm,pairs,R,t)
    return best
DON={'S','T','Y','N','Q','K','R','W','H','C'}; ACC={'S','T','Y','N','Q','D','E','H'}; CHG={'D':-1,'E':-1,'K':1,'R':1}
IDS={'1EEM':'GSTO1','6GSS':'GSTP1','2C3Q':'GSTT2','1LJR':'GSTT1','7AIA':'GDAP1'}
S={p:get(p) for p in IDS}
CH={p:(['AAA'] if p=='7AIA' else None) for p in IDS}
res={}; lig={}
for p in IDS:
    prot,het=S[p]
    if p=='7AIA':
        res[p]=[r for r in prot['AAA'] if 'CA' in r['atoms'] and 23<=r['resi']<=302]; lig[p]=None
    else:
        cands={}
        for c,resn,resi,name,xyz in het:
            if resn in ('GSH','GTX'): cands.setdefault((c,resi),[]).append((name,xyz))
        k=max(cands,key=lambda k:len(cands[k])); lig[p]=([n for n,_ in cands[k]],np.array([x for _,x in cands[k]]))
        res[p]=[r for r in prot[k[0]] if 'CA' in r['atoms']]
X={p:np.array([r['atoms']['CA'] for r in res[p]]) for p in IDS}
order=list(IDS)
A={}
for i,a in enumerate(order):
    for b in order[i+1:]:
        tm,pairs,R,t=tmalign(X[a],X[b]); A[(a,b)]=(tm,{i_:j for i_,j in pairs},R,t); A[(b,a)]=(tm,{j:i_ for i_,j in pairs},None,None)
def tally(host,query):
    """GSH bound to `host`; ask what the structurally equivalent residues in `query` provide."""
    tm,m,R,t=A[(host,query)]; LN,LA=lig[host]
    if R is None: tm,m2,R2,t2=A[(query,host)]; inv={v:k for k,v in m2.items()}; m=inv; R,t=R2,t2; fwd=False
    else: fwd=True
    out={'backbone_retained':0,'sidechain_retained':0,'sidechain_lost':0,'unmapped':0}
    hc=sc=0; nmap=0
    for ri,r in enumerate(res[host]):
        at={k:v for k,v in r['atoms'].items() if not k.startswith('H')}
        AA_=np.array(list(at.values())); nm=list(at)
        D=np.linalg.norm(AA_[:,None,:]-LA[None,:,:],axis=2)
        if D.min()>8.0: continue
        qi=m.get(ri)
        if qi is None: dev=np.nan
        else:
            if fwd: dev=float(np.linalg.norm((X[host][ri]@R.T+t)-X[query][qi]))
            else:   dev=float(np.linalg.norm((X[query][qi]@R.T+t)-X[host][ri]))
        mapped = qi is not None and dev<5.0
        if mapped: nmap+=1; hc+=CHG.get(r['aa'],0); sc+=CHG.get(res[query][qi]['aa'],0)
        if D.min()>4.5: continue
        for a_i,an in enumerate(nm):
            if an[0] not in 'NO': continue
            for b_i,bn in enumerate(LN):
                if bn[0] not in 'NOS' or D[a_i,b_i]>3.5: continue
                if an in ('N','O','OXT'): out['backbone_retained' if mapped else 'unmapped']+=1
                elif not mapped: out['unmapped']+=1
                else:
                    don = an[0]=='N' or (an[0]=='O' and r['aa'] in ('S','T','Y'))
                    ok = (res[query][qi]['aa'] in DON) if don else (res[query][qi]['aa'] in ACC)
                    out['sidechain_retained' if ok else 'sidechain_lost']+=1
    return dict(host=host,host_gene=IDS[host],query=query,query_gene=IDS[query],TM=round(tm,3),
                n_shell=nmap,host_charge=hc,query_charge=sc,**out)
rows=[tally(h,q) for h in ['1EEM','6GSS','2C3Q','1LJR'] for q in IDS if q!=h]
R=pd.DataFrame(rows)
R['sc_total']=R.sidechain_retained+R.sidechain_lost
R['frac_sc_lost']=(R.sidechain_lost/R.sc_total).round(3)
R['charge_delta']=R.query_charge-R.host_charge
print(R[['host_gene','query_gene','TM','backbone_retained','sidechain_retained','sidechain_lost','frac_sc_lost','n_shell','host_charge','query_charge','charge_delta']].to_string(index=False))
g=R[R.query_gene=='GDAP1']; o=R[R.query_gene!='GDAP1']
