print("per-complex fraction lost, GDAP1 %s vs cross-class median %.2f, Mann-Whitney U p=%.3f"%(list(g.frac_sc_lost),o.frac_sc_lost.median(),u.pvalue))
print("charge delta GDAP1 mean %.2f vs cross-class mean %.2f, MWU p=%.3f"%(g.charge_delta.mean(),o.charge_delta.mean(),
